using System;
using System.Collections.Generic;
using UnityEngine;

// Self-contained room: every side has one wall slot per tile. Each slot can show a wall, a window, an inner
// door, an outer (front) door or nothing (when the neighbour room already provides that wall).
// Slots are generated by RoomPrefabBuilder / HousePackRoomBuilder as Structure/Slots/{Side}_{index}/{Wall|Window|DoorInner|DoorOuter}.
// House-pack rooms also have Structure/Corners/{NE|NW|SE|SW} and Structure/Roof + Structure/RoofNoEave; older rooms
// lack those children and simply ignore the related settings.
public class RoomLayout : MonoBehaviour
{
    public enum Side { North, East, South, West }
    public enum SlotMode { Wall, InnerDoor, OuterDoor, Empty, Window }

    [Serializable]
    public class DoorPlacement
    {
        public Side side;
        public int slotIndex;
        public bool isFrontDoor;
    }

    [Serializable]
    public class WindowPlacement
    {
        public Side side;
        public int slotIndex;
    }

    [Header("Size (tiles)")]
    [SerializeField] private int width = 3;
    [SerializeField] private int depth = 3;

    [Header("Sides without walls (shared with a neighbour room)")]
    [SerializeField] private List<Side> openSides = new List<Side>();

    [Header("Doors")]
    [SerializeField] private List<DoorPlacement> doors = new List<DoorPlacement>();

    [Header("Windows (house-pack rooms only)")]
    [SerializeField] private List<WindowPlacement> windows = new List<WindowPlacement>();

    [Tooltip("Use the eave-less roof (house-pack rooms only), for rooms whose slope meets a neighbour room.")]
    [SerializeField] private bool noEaveRoof;

    public int Width => width;
    public int Depth => depth;

    // The settings on this component are the source of truth; slot visibility is rebuilt from them,
    // so re-generating the room prefab never loses a level's door setup.
    private void Awake()
    {
        Apply();
    }

    public void SetSize(int width, int depth)
    {
        this.width = width;
        this.depth = depth;
    }

    public void Configure(List<Side> openSides, List<DoorPlacement> doors)
    {
        Configure(openSides, doors, null, false);
    }

    public void Configure(List<Side> openSides, List<DoorPlacement> doors, List<WindowPlacement> windows, bool noEaveRoof)
    {
        this.openSides = openSides ?? new List<Side>();
        this.doors = doors ?? new List<DoorPlacement>();
        this.windows = windows ?? new List<WindowPlacement>();
        this.noEaveRoof = noEaveRoof;
        Apply();
    }

    public int GetSlotCount(Side side)
    {
        return side == Side.North || side == Side.South ? width : depth;
    }

    [ContextMenu("Apply Layout")]
    public void Apply()
    {
        Transform structure = transform.Find("Structure");
        Transform slots = structure != null ? structure.Find("Slots") : null;
        if (slots == null) return;

        foreach (Side side in Enum.GetValues(typeof(Side)))
        {
            for (int i = 0; i < GetSlotCount(side); i++)
            {
                Transform slot = slots.Find(side + "_" + i);
                if (slot == null) continue;
                SetSlot(slot, GetMode(side, i));
            }
        }

        // A corner trim shows only where this room draws both walls that meet there.
        Transform corners = structure.Find("Corners");
        if (corners != null)
        {
            SetChild(corners, "NE", HasWalls(Side.North) && HasWalls(Side.East));
            SetChild(corners, "NW", HasWalls(Side.North) && HasWalls(Side.West));
            SetChild(corners, "SE", HasWalls(Side.South) && HasWalls(Side.East));
            SetChild(corners, "SW", HasWalls(Side.South) && HasWalls(Side.West));
        }

        if (structure.Find("RoofNoEave") != null)
        {
            SetChild(structure, "Roof", !noEaveRoof);
            SetChild(structure, "RoofNoEave", noEaveRoof);
        }
    }

    private bool HasWalls(Side side)
    {
        return !openSides.Contains(side);
    }

    private SlotMode GetMode(Side side, int index)
    {
        foreach (var door in doors)
        {
            if (door.side == side && door.slotIndex == index) return door.isFrontDoor ? SlotMode.OuterDoor : SlotMode.InnerDoor;
        }
        if (openSides.Contains(side)) return SlotMode.Empty;
        foreach (var window in windows)
        {
            if (window.side == side && window.slotIndex == index) return SlotMode.Window;
        }
        return SlotMode.Wall;
    }

    private static void SetSlot(Transform slot, SlotMode mode)
    {
        // Rooms without a window part keep a plain wall there.
        if (mode == SlotMode.Window && slot.Find("Window") == null) mode = SlotMode.Wall;
        SetChild(slot, "Wall", mode == SlotMode.Wall);
        SetChild(slot, "Window", mode == SlotMode.Window);
        SetChild(slot, "DoorInner", mode == SlotMode.InnerDoor);
        SetChild(slot, "DoorOuter", mode == SlotMode.OuterDoor);
    }

    private static void SetChild(Transform parent, string name, bool active)
    {
        Transform child = parent.Find(name);
        if (child == null || child.gameObject.activeSelf == active) return;
        child.gameObject.SetActive(active);
#if UNITY_EDITOR
        if (!Application.isPlaying && UnityEditor.PrefabUtility.IsPartOfPrefabInstance(child.gameObject))
            UnityEditor.PrefabUtility.RecordPrefabInstancePropertyModifications(child.gameObject);
#endif
    }

#if UNITY_EDITOR
    private void OnValidate()
    {
        // SetActive is not allowed inside OnValidate, defer it.
        if (UnityEditor.PrefabUtility.IsPartOfPrefabAsset(this)) return;
        UnityEditor.EditorApplication.delayCall += () => { if (this != null) Apply(); };
    }
#endif
}
